import {EVENTS,NODES,COLORS,loadProgress,grant,discover,buy,rank} from './model.mjs';
import {ARTISTS,CARD_QUESTIONS,PHILOSOPHY} from './content-data.mjs';
import {SeaWorld} from './world.mjs';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let p;try{p=loadProgress(localStorage);}catch{p=loadProgress({getItem:()=>null});}
let travelHandler=null;
let lang=p.lang==='en'?'en':'es',screen='welcome',world=null,nearby=null,waypoint=null,modalId='',toastTimer,saveTimer=0,storageWarned=false,primaryPointer=null,secondPointer=null,origin=null,radio=null,currentTrack=-1,transitioning=false;
const t=(es,en)=>lang==='es'?es:en;
const texts={pilot:['PRIMERA EXPEDICIÓN · PILOTO','FIRST EXPEDITION · PILOT'],coordinates:['UN PLANETA. TODAS LAS FRECUENCIAS.','ONE PLANET. EVERY FREQUENCY.'],welcomeText:['Hay un lugar para quienes escuchan más allá. Tu próxima aventura empieza en el mar.','There’s a place for those who listen beyond. Your next adventure begins at sea.'],enter:['Entrar al planeta <span>↗</span>','Enter the planet <span>↗</span>'],createPassport:['Crear mi pasaporte de prueba','Create my pilot passport'],guestNote:['Puedes explorar sin cuenta. El piloto guarda tu progreso en este navegador.','Explore without an account. This pilot saves your progress in this browser.'],planetCaption:['BOIA.PLANET<br>UN LUGAR POR DESCUBRIR','BOIA.PLANET<br>A PLACE TO DISCOVER'],genres:['ELECTRÓNICA · LIVE · REGGAETÓN · ROCK · Y MÁS','ELECTRONIC · LIVE · REGGAETON · ROCK · MORE'],directTickets:['Ir directamente a entradas ↗','Go straight to tickets ↗'],independent:['ESPÍRITU INDEPENDIENTE. SONIDO GLOBAL.','INDEPENDENT SPIRIT. GLOBAL SOUND.'],homeText:['Para amantes de toda la música.<br>Para quienes siempre quieren descubrir algo más.','For lovers of all music.<br>For those who always want to discover more.'],explore:['Explorar el universo <span>↗</span>','Explore the universe <span>↗</span>'],exploreNote:['Tres islas. Seis boyas. Tu propia aventura.','Three islands. Six buoys. Your own adventure.'],secret:['PRÓXIMA PARADA<br>SECRET LOCATION','NEXT STOP<br>SECRET LOCATION'],tickets:['Entradas','Tickets'],artists:['Artistas','Artists'],gallery:['Fotos y vídeos','Photos & videos'],shop:['Tienda','Shop'],philosophy:['La filosofía BOIA','The BOIA philosophy'],backFestival:['← Festival','← Festival'],voyage:['CARTA DE NAVEGACIÓN','NAVIGATION CHART'],touchBoat:['Toca el barco y arrastra para navegar.','Touch the boat and drag to sail.'],driftHelp:['Mantén un segundo dedo sobre el mar para derrapar. En ordenador: WASD / flechas y Espacio.','Hold a second finger on the sea to drift. On desktop: WASD / arrows and Space.'],map:['ARCHIPIÉLAGO BOIA','BOIA ARCHIPELAGO'],mapHelp:['Toca una isla para marcar el rumbo','Tap an island to set a course'],myBoat:['Mi barco','My boat'],bottle:['Mensaje en botella','Message in a bottle'],knots:['NUDOS','KNOTS'],fallbackTitle:['El océano necesita un dispositivo con 3D.','The ocean needs a device with 3D support.'],fallbackText:['Puedes seguir viendo los eventos, artistas y recuerdos desde la portada.','You can still explore events, artists and memories from the festival page.']};
function translate(){document.documentElement.lang=lang;all('[data-i18n]').forEach(el=>{const a=texts[el.dataset.i18n];if(a)el.innerHTML=a[lang==='es'?0:1];});$('#lang').textContent=lang==='es'?'EN':'ES';$('#passport-button').textContent=p.nickname||t('Mi pasaporte','My passport');if($('#achievements-btn'))$('#achievements-btn').textContent=t('Logros','Achievements');$('#close-panel').ariaLabel=t('Cerrar','Close');$('.brand').ariaLabel=t('BOIA inicio','BOIA home');updateHUD();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){p.lang=lang;try{localStorage.setItem('boia.planet.pilot.v1',JSON.stringify(p));}catch{if(!storageWarned){storageWarned=true;toast(t('Este navegador no permite guardar el progreso.','This browser cannot save your progress.'));}}window.dispatchEvent(new Event('boia-save'));}
function setScreen(next){screen=next;document.body.dataset.screen=next;for(const id of ['welcome','home','game'])$('#'+id).hidden=id!==next;$('#fallback').hidden=true;world?.setMode(next);updateHUD();}
function transition(next){if(transitioning)return;transitioning=true;clearControls();setScreen(next);setTimeout(()=>{transitioning=false;},350);}
function explore(target){closePanel();if(!world){$('#fallback').hidden=false;return;}waypoint=target?EVENTS.find(e=>e.id===target):null;transition('game');}
function openPanel(id,html,kicker='BOIA.PLANET'){clearControls();modalId=id;$('#panel-kicker').textContent=kicker;$('#panel-content').innerHTML=html;if(!$('#panel').open)$('#panel').showModal();if(world)world.paused=true;$('#panel').scrollTop=0;}
function closePanel(){if($('#panel').open)$('#panel').close();modalId='';if(world)world.paused=false;}
function sampleNote(){return `<p class="panel-note">${t('Piloto de presentación. Eventos, carteles y ofertas de muestra; no hay ventas ni descuentos reales.','Presentation pilot. Sample events, posters and offers; no real sales or discounts.')}</p>`;}
function poster(e){return `<div class="poster ${e.id}"><span class="poster-brand">BOIA.PLANET / ${e.label}</span><strong class="poster-title">${e.id==='halloween'?'HALLO<br>WEEN':e.id==='christmas'?t('NAVIDAD<br>A LA DERIVA','CHRISTMAS<br>ADRIFT'):t('EL ÚLTIMO<br>BAILE','THE LAST<br>DANCE')}</strong><span class="poster-meta">UNDERGROUND MUSIC FESTIVAL<br>${e.tag}<br>SECRET LOCATION</span></div>`;}
function tickets(){openPanel('tickets',`<h2>${t('Tu próxima<br>pista de baile.','Your next<br>dancefloor.')}</h2><p>${t('Tres encuentros. Un mismo espíritu. Elige dónde nos encontramos.','Three gatherings. One shared spirit. Choose where we meet.')}</p><div class="event-grid">${[...EVENTS].reverse().map(e=>`<article class="event-card">${poster(e)}<button data-event="${e.id}">${t('Ver evento','View event')} ↗</button></article>`).join('')}</div>${sampleNote()}`,t('ELIGE TU PRÓXIMA ISLA','CHOOSE YOUR NEXT ISLAND'));}
function eventPanel(id){if(screen==='home'&&world&&travelHandler){travelHandler(id,()=>eventPanel(id));return;}const e=EVENTS.find(v=>v.id===id);if(!e)return;const codeUnlocked=id==='halloween'?p.rewards.includes('rescue'):p.discovered.includes(id==='christmas'?'christmas-discount':'newyear-discount');openPanel('event:'+id,`<div class="event-detail">${poster(e)}<div class="event-meta"><h2>${lang==='es'?e.name:e.en}</h2><p>${e.genres}</p><p><b>${t('Fecha por anunciar','Date to be announced')}</b><br>Secret location</p><button class="primary" data-action="checkout" data-id="${e.id}">${t('Ver entradas de muestra','View sample tickets')} ↗</button><p class="sail-invite">${t('También puedes encontrar sorpresas navegando hasta su isla.','You can also find surprises by sailing to its island.')}</p><button class="secondary" data-sail="${e.id}">${t('Navegar hasta su isla','Sail to its island')}</button><button class="text-btn" data-gallery="${e.id}">${t('Recuerdos de esta isla','Memories from this island')}</button>${codeUnlocked?`<div class="coupon"><b>${e.code}</b><button data-copy="${e.code}">${t('Copiar','Copy')}</button></div><small>${t('10% de muestra. Sin validez comercial.','Sample 10%. No commercial value.')}</small>`:''}</div></div>${sampleNote()}`,`ISLA ${e.label} / ${e.tag}`);}
function checkout(id){const e=EVENTS.find(v=>v.id===id)||EVENTS[0];openPanel('checkout',`<h2>${t('Entradas de','Tickets for')}<br>${lang==='es'?e.name:e.en}</h2><div class="notice">${t('Aquí se abrirá la ticketera oficial. Esta versión permite revisar el recorrido; todavía no se puede comprar ni introducir datos de pago.','The official ticket platform will open here. This version lets you review the journey; purchases and payment details are not enabled.')}</div><button class="primary" data-sail="${e.id}">${t('Explorar la isla','Explore the island')} ↗</button>${sampleNote()}`);}
function artists(){if(screen==='home'&&world&&travelHandler){travelHandler('artists',artists);return;}openPanel('artists',`<h2>${t('Personas detrás<br>del sonido.','People behind<br>the sound.')}</h2><p>${t('De la A a la Z. Diferentes orígenes, una misma pista.','A to Z. Different origins, one shared dancefloor.')}</p><div class="artist-list">${ARTISTS.map((a,i)=>`<button class="artist-row" data-artist="${i}"><img class="artist-avatar" src="${a.avatar}" alt="${t('Avatar provisional','Provisional avatar')}"><span><strong>${a.name}</strong><small>${a.genre}</small></span><span>↗</span></button>`).join('')}</div><p class="panel-note">${t('Selección facilitada por BOIA. Retratos y respuestas personales pendientes de cada artista.','Selection supplied by BOIA. Portraits and personal answers await each artist.')}</p><button class="secondary" data-action="passport">${t('Crear mi Carnet BOIA','Create my BOIA Card')} ↗</button>`);}
function artistPanel(i){const a=ARTISTS[i];if(!a)return;if(screen==='home'&&world&&travelHandler){travelHandler('artists',()=>artistPanel(i));return;}openPanel('artist:'+i,`<span class="eyebrow">CARNET BOIA / ${t('ARTISTA','ARTIST')}</span><h2>${a.name}</h2><div class="passport-card"><img src="${a.avatar}" alt="${t('Avatar provisional','Provisional avatar')}"><div><h3>${a.genre}</h3><span class="stamp">BOIA ARTIST</span></div></div><p class="panel-note">${t('Avatar provisional. Su fotografía y su historia llegarán de la mano del artista.','Provisional avatar. The artist will provide their photograph and story.')}</p>${CARD_QUESTIONS.map(q=>`<div class="card-answer"><small>${t(...q)}</small><p>${t('Una historia por compartir.','A story still to be shared.')}</p></div>`).join('')}<button class="secondary" data-action="passport">${t('Crear mi Carnet BOIA','Create my BOIA Card')}</button>`);}
function gallery(event){if(screen==='home'&&world&&travelHandler){travelHandler('gallery',()=>gallery(event));return;}const e=EVENTS.find(e=>e.id===event);openPanel('gallery'+(event?':'+event:''),`<h2>${e?(lang==='es'?e.name:e.en):t('El puerto de<br>los recuerdos.','The harbour<br>of memories.')}</h2><p>${t('La música termina. Lo que vivimos se queda.','The music ends. What we lived stays with us.')}</p><div class="gallery-grid"><figure><img src="../assets/beach-demo.webp" alt="${t('Escena de fiesta junto al mar, imagen de muestra','Seaside party scene, sample image')}" loading="lazy"><figcaption>${t('Bajo el sol · Imagen de muestra','Under the sun · Sample image')}</figcaption></figure><figure><img src="../assets/decks-demo.webp" alt="${t('Cabina musical, imagen de muestra','DJ booth, sample image')}" loading="lazy"><figcaption>${t('Detrás del sonido · Imagen de muestra','Behind the sound · Sample image')}</figcaption></figure></div><div class="notice">${t('Este puerto mostrará las fotos y vídeos de cada edición. Las imágenes del piloto son ilustrativas; los vídeos reales están pendientes.','This harbour will show photos and videos from each edition. Pilot images are illustrative; real videos are still pending.')}</div>`);}
function philosophy(){openPanel('philosophy',`<span class="eyebrow">${t('DAR ESPACIO · DESCUBRIR · PERTENECER','MAKE ROOM · DISCOVER · BELONG')}</span><h2>${t('Un espacio para<br>lo que viene.','Room for<br>what comes next.')}</h2>${PHILOSOPHY.map(q=>`<p>${t(...q)}</p>`).join('')}<blockquote>${t('No vienes simplemente a BOIA. Formas parte de BOIA.','You don’t simply come to BOIA. You are part of BOIA.')}</blockquote><button class="primary" data-action="explore">${t('Explorar el universo','Explore the universe')} ↗</button>`);}
function passport(edit=false){if(p.nickname&&!edit){openPanel('passport',`<h2>${t('Tu carta<br>de navegante.','Your navigation<br>card.')}</h2><div class="passport-card"><img src="../assets/mascot.jpeg" alt="Mascota BOIA"><div><h3>${esc(p.nickname)}</h3><span class="stamp">${rank(p,lang)}</span><p>${p.points} ${t('puntos','points')} / ${p.coins} ${t('monedas','coins')}</p><p>${esc(p.genres)}</p></div></div>${p.artist?`<p><b>${t('Un artista con quien bailar:','An artist to dance with:')}</b> ${esc(p.artist)}</p>`:''}${p.memory?`<p>${esc(p.memory)}</p>`:''}${p.message?`<p>“${esc(p.message)}”</p>`:''}<div class="notice">${t('Pasaporte de prueba guardado solo en este navegador. Todavía no es un perfil público ni una cuenta recuperable por email.','Pilot passport saved only in this browser. It is not yet a public profile or an email-recoverable account.')}</div><button class="secondary" data-action="editPassport">${t('Editar mi carta','Edit my card')}</button> <button class="secondary" data-action="boat">${t('Personalizar barco','Customise boat')}</button>`);return;}
 openPanel('passport-edit',`<h2>${t('Todo capitán<br>tiene una historia.','Every captain<br>has a story.')}</h2><p>${t('Empieza por tu apodo. El resto puedes completarlo cuando quieras.','Start with your nickname. You can fill in the rest whenever you like.')}</p><form id="passport-form" class="passport-form"><label>${t('Tu apodo','Your nickname')}<input name="nickname" maxlength="24" required value="${esc(p.nickname)}" placeholder="${t('Capitán Marea','Captain Tide')}" autocomplete="nickname"></label><label>${t('Géneros que te mueven','Genres that move you')}<input name="genres" maxlength="100" value="${esc(p.genres)}" placeholder="House, rock, reggaetón…"></label><label class="full">${t('Un artista con el que has bailado mucho','An artist you have danced to a lot')}<input name="artist" maxlength="100" value="${esc(p.artist)}"></label><label class="full">${t('Tu mejor recuerdo de un festival','Your favourite festival memory')}<textarea name="memory" maxlength="350" rows="2">${esc(p.memory)}</textarea></label><label class="full">${t('Algo que quieras compartir','Something you want to share')}<textarea name="message" maxlength="200" rows="2">${esc(p.message)}</textarea></label><div class="notice full">${t('Este piloto no pide email ni crea una cuenta. Tu carta y progreso se guardan en este navegador. En la versión definitiva, te avisaremos antes de crear el perfil público.','This pilot does not request an email or create an account. Your card and progress stay in this browser. The final version will explain public profiles before you create one.')}</div><button class="primary full" type="submit">${t('Guardar mi pasaporte de prueba','Save my pilot passport')} ↗</button></form>`);}
function boatPanel(){openPanel('boat',`<h2>${t('Tu barco.<br>Tu bandera.','Your boat.<br>Your flag.')}</h2><p>${t('Los cambios son visuales. Todos navegamos con las mismas posibilidades.','These changes are cosmetic. Everyone sails with the same possibilities.')}</p><b>${p.coins} ${t('monedas disponibles','coins available')}</b><p>${t('Color del casco · Gratis','Hull colour · Free')}</p><div class="swatches">${COLORS.map((c,i)=>`<button class="swatch ${p.color===c?'selected':''}" style="background:${c}" data-color="${c}" aria-label="${t('Color','Colour')} ${i+1}" aria-pressed="${p.color===c}"></button>`).join('')}</div><div class="inventory"><button data-buy="flag"><strong>${t('Bandera BOIA','BOIA flag')}</strong><span>${p.owned.includes('flag')?(p.flag?t('Equipada · Quitar','Equipped · Remove'):t('Equipar','Equip')):t('40 monedas','40 coins')}</span></button><button data-buy="trail"><strong>${t('Estela coral','Coral wake')}</strong><span>${p.owned.includes('trail')?(p.trail?t('Equipada · Quitar','Equipped · Remove'):t('Equipar','Equip')):t('60 monedas','60 coins')}</span></button></div><p class="panel-note">${t('Modelos y otros accesorios quedan para la siguiente etapa. Descubre boyas y sorpresas para ganar monedas.','Boat models and other accessories come in the next stage. Find buoys and surprises to earn coins.')}</p><button class="primary" data-action="explore">${t('Volver al mar','Back to sea')} ↗</button>`);}
function achievements(){const foundBuoys=NODES.filter(n=>n.kind==='buoy'&&p.discovered.includes(n.id)).length,foundIslands=EVENTS.filter(e=>p.discovered.includes(e.id)).length;const list=[{title:t('Primera BOIA encontrada','First BOIA found'),desc:t('Encuentra una boya','Find a buoy'),done:foundBuoys>0,progress:`${Math.min(1,foundBuoys)} / 1`},{title:t('Coleccionista de BOIAs','BOIA collector'),desc:t('Descubre las seis boyas','Find all six buoys'),done:foundBuoys===6,progress:`${foundBuoys} / 6`},...EVENTS.map(e=>({title:lang==='es'?e.name:e.en,desc:t('Descubre la isla','Discover the island'),done:p.discovered.includes(e.id),progress:p.discovered.includes(e.id)?'1 / 1':'0 / 1'})),{title:t('Todo el archipiélago','The whole archipelago'),desc:t('Visita las tres islas','Visit all three islands'),done:foundIslands===3,progress:`${foundIslands} / 3`},{title:t('Nadie se queda atrás','No one left behind'),desc:t('Ayuda al náufrago','Help the castaway'),done:p.rewards.includes('rescue'),progress:p.rewards.includes('rescue')?'1 / 1':'0 / 1'},...[5,20].map(m=>({title:t(`${m} minutos al timón`,`${m} minutes at the helm`),desc:t('Tiempo navegando acumulado','Accumulated sailing time'),done:p.activeSeconds>=m*60,progress:`${Math.min(m,Math.floor(p.activeSeconds/60))} / ${m}`}))];openPanel('achievements',`<h2>${t('Cada viaje<br>deja una marca.','Every journey<br>leaves a mark.')}</h2><p>${rank(p,lang)} / ${p.points} ${t('puntos acumulados','total points')}</p>${list.map(a=>`<div class="achievement ${a.done?'earned':''}"><span class="seal">${a.done?'✓':'◇'}</span><div><strong>${a.title}</strong><small>${a.desc}</small></div><span>${a.progress}</span></div>`).join('')}<p class="panel-note">${t('Recompensas una sola vez. Gastar monedas no reduce tu rango. Los logros por compra llegarán con la ticketera real.','Rewards are granted once. Spending coins does not lower your rank. Purchase achievements will arrive with the real ticket platform.')}</p>`);}
function shop(){if(screen==='home'&&world&&travelHandler){travelHandler('shop',()=>shop());return;}openPanel('shop',`<h2>${t('Un pedazo<br>de BOIA contigo.','A little BOIA<br>wherever you go.')}</h2><div class="shop-list">${[[t('Camiseta BOIA','BOIA T-shirt'),t('Algodón. Azul mar o naranja.','Cotton. Ocean blue or orange.')],[t('Tote de navegante','Navigator tote'),t('Para los discos y todo lo que venga.','For records and whatever comes next.')],[t('Pack de pegatinas','Sticker pack'),t('Pequeñas señales de otro planeta.','Little signals from another planet.')]].map((v,i)=>`<div class="shop-item"><div><h3>${v[0]}</h3><p>${v[1]}</p></div><button class="secondary" data-product="${i}">${t('Ver producto','View product')} ↗</button></div>`).join('')}</div><p>${t('Envío a domicilio o recogida en fiesta.','Home delivery or pickup at an event.')}</p><div class="notice">${t('Catálogo conceptual. Fotos, tallas, precios y existencias se añadirán con los productos reales. No se realizan pedidos en este piloto.','Concept catalogue. Photos, sizes, prices and stock will be added with the real products. Orders are not enabled in this pilot.')}</div>`);}
function product(id){if(screen==='home'&&world&&travelHandler){travelHandler('shop',()=>product(id));return;}const names=[t('Camiseta BOIA','BOIA T-shirt'),t('Tote de navegante','Navigator tote'),t('Pack de pegatinas','Sticker pack')];openPanel('product',`<h2>${names[id]||names[0]}</h2><p>${t('Producto de muestra para presentar la futura tienda.','Sample product to demonstrate the future shop.')}</p><label>${t('Entrega','Delivery')} <select id="delivery-choice"><option>${t('Envío a domicilio','Home delivery')}</option><option>${t('Recogida en fiesta','Event pickup')}</option></select></label><div class="notice">${t('Precio y disponibilidad pendientes. No se generará ningún pedido.','Price and availability pending. No order will be created.')}</div><button class="secondary" data-action="shop">${t('Volver a la tienda','Back to shop')}</button>`);}
function bottle(){openPanel('bottle',`<h2>${t('Tu oído<br>nos guía.','Your ears<br>guide us.')}</h2><p>${t('Una misión voluntaria: ayúdanos a imaginar la próxima BOIA.','An optional mission: help us imagine the next BOIA.')}</p><form id="survey-form" class="passport-form"><label class="full">${t('¿Qué artistas has visto en BOIA?','Which artists have you seen at BOIA?')}<input name="seen" maxlength="200" value="${esc(p.survey?.seen||'')}"></label><label class="full">${t('¿Cuál te ha gustado más?','Who did you enjoy most?')}<input name="favourite" maxlength="100" value="${esc(p.survey?.favourite||'')}"></label><label class="full">${t('¿A quién te gustaría escuchar después?','Who would you like to hear next?')}<input name="next" maxlength="100" required value="${esc(p.survey?.next||'')}"></label><button type="submit" class="primary full">${t('Guardar respuesta de prueba','Save pilot response')} ↗</button></form><p class="panel-note">${t('Opcional. Las respuestas del piloto se guardan solo aquí; no se envían al equipo. La primera respuesta regala 20 monedas, sea cual sea tu opinión.','Optional. Pilot answers stay in this browser and are not sent to the team. The first response earns 20 coins, whatever your opinion.')}</p>`);}
function soundPanel(){openPanel('music',`<h2>Radio BOIA</h2><p>${t('Cuatro ambientes originales de muestra para navegar. Se sustituirán por vuestras canciones.','Four original sample soundscapes for sailing. They will be replaced with your tracks.')}</p><div class="sound-list">${['Blue Current','Low Tide','Orange Moon','Last Light'].map((v,i)=>`<button data-track="${i}" class="${currentTrack===i?'active':''}"><span>0${i+1} / ${v}</span><span>${currentTrack===i?'Ⅱ':'▷'}</span></button>`).join('')}</div><button class="secondary" data-action="mute">${t('Silenciar radio','Mute radio')}</button><p class="panel-note">${t('Sonidos sintetizados para el piloto. Sin canciones ni artistas reales.','Synthesised pilot sounds. No real songs or artists.')}</p>`);}
function playTrack(i){if(currentTrack===i){stopRadio();soundPanel();return;}stopRadio();const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){toast(t('Audio no disponible.','Audio unavailable.'));return;}const ctx=new Audio();ctx.resume().catch(()=>{});const gain=ctx.createGain();gain.gain.value=.045;const master=ctx.createGain();let volume=.4;try{volume=Number(JSON.parse(localStorage.getItem('boia.settings')||'{}').music??40)/100;}catch{}master.gain.value=volume;gain.connect(master);master.connect(ctx.destination);const chord=[[130.81,164.81,196,246.94],[110,130.81,164.81,220],[146.83,174.61,220,261.63],[98,123.47,146.83,196]][i];const oscs=chord.map((freq,j)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type=j%2?'sine':'triangle';o.frequency.value=freq;g.gain.value=j? .2:.3;o.connect(g);g.connect(gain);o.start();return o;});let step=0;const timer=setInterval(()=>{const now=ctx.currentTime;gain.gain.cancelScheduledValues(now);gain.gain.setValueAtTime(.028,now);gain.gain.linearRampToValueAtTime(.06,now+.07);gain.gain.linearRampToValueAtTime(.025,now+.38);oscs[0].frequency.setTargetAtTime(chord[step++%4]/2,now,.04);},[490,610,540,680][i]);radio={ctx,timer,master};currentTrack=i;soundPanel();}
function stopRadio(){if(radio){clearInterval(radio.timer);radio.ctx.close().catch(()=>{});radio=null;}currentTrack=-1;}
function visit(node){if(!node)return;const wasNew=discover(p,node.id);if(wasNew){if(node.kind==='buoy'&&!p.rewards.includes('first-buoy'))grant(p,'first-buoy',20);const buoyN=NODES.filter(n=>n.kind==='buoy'&&p.discovered.includes(n.id)).length;if(buoyN===6)grant(p,'all-buoys',40);if(EVENTS.every(e=>p.discovered.includes(e.id)))grant(p,'all-islands',40);save();toast(t('Nuevo descubrimiento. +20 monedas','New discovery. +20 coins'));}updateHUD();
 if(node.kind==='event'){eventPanel(node.id);if(node.id==='newyear'){$('#panel-content').insertAdjacentHTML('beforeend',`<div class="notice">${t('Has llegado al último baile. La aventura sigue: vuelve al mar y encuentra todos los descuentos, boyas y sorpresas que te faltan.','You have reached the last dance. The adventure continues: return to sea and find every discount, buoy and surprise you have missed.')}</div>`);save();}return;}
 if(node.id==='history'){philosophy();return;}if(node.id==='music'){soundPanel();return;}if(node.id==='gallery'){gallery();return;}if(node.id==='lighthouse'){openPanel('lighthouse',`<h2>${t('El faro<br>de batalla.','The battle<br>lighthouse.')}</h2><p>${t('Próximamente: minijuegos y nuevos retos para la tripulación. Por ahora, su luz marca el horizonte.','Coming soon: mini-games and new challenges for the crew. For now, its light marks the horizon.')}</p><button class="primary" data-action="resume">${t('Volver a navegar','Back to sailing')} ↗</button>`);return;}
 if(node.id==='fiestera'){openPanel('fiestera',`<h2>${t('¡Capitán!<br>Yo me apunto.','Captain!<br>I’m coming too.')}</h2><div class="passport-card"><img src="../assets/mascot.jpeg" alt="BOIA"><div><h3>LA BOIA FIESTERA</h3><p>${t('“Me han dicho que en Nochevieja nadie quiere volver a puerto. ¿Me ayudas a llegar?”','“I heard that on New Year’s Eve nobody wants to return to port. Will you help me get there?”')}</p></div></div><p>${t('Tu misión: descubre las islas y lleva el espíritu BOIA hasta el último baile.','Your mission: discover the islands and take the BOIA spirit to the last dance.')}</p><button class="primary" data-action="resume">${t('¡Sube a bordo!','Come aboard!')} ↗</button>`);return;}
 if(node.id==='castaway'){const helped=p.rewards.includes('rescue');openPanel('castaway',`<h2>${t('¡Eh, por aquí!','Hey, over here!')}</h2><p>${t('“He perdido el barco, las chanclas y casi la dignidad… pero todavía llego al primer tema. ¿Me acercas a Halloween, porfa?”','“I lost my boat, my flip-flops and almost my dignity… but I can still make the opening track. Could you take me to Halloween?”')}</p>${helped?couponHTML('DEMO-HALLOW10'): `<button class="primary" data-action="rescue">${t('Claro, ¡sube a bordo!','Of course, hop aboard!')} ↗</button>`}<p class="panel-note">${t('Al ayudarle consigues el código de muestra del 10% para Halloween.','Help him to get the sample 10% Halloween code.')}</p>`);return;}
 if(node.id==='treasure'){grant(p,'treasure',30);save();openPanel('treasure',`<h2>${t('No todo tesoro<br>es oro.','Not every treasure<br>is gold.')}</h2><p>${t('Entre las maderas aparece una nota: “Para quien nunca deja de buscar”. +30 monedas la primera vez y un código de muestra del 20% en tienda.','Among the driftwood is a note: “For whoever never stops looking.” +30 coins on the first find and a sample 20% shop code.')}</p>${couponHTML('DEMO-TIENDA20')}<button class="secondary" data-action="shop">${t('Visitar la tienda','Visit the shop')}</button>${sampleNote()}`);return;}
 if(node.id==='whatsapp'){openPanel('whatsapp',`<h2>${t('Encuentra<br>tu tripulación.','Find<br>your crew.')}</h2><p>${t('La comunidad BOIA sigue en tierra. Al unirte al grupo de WhatsApp, un pack de pegatinas acompañará tu primera compra de un producto.','The BOIA community continues on land. Join the WhatsApp group to get a sticker pack with your first product purchase.')}</p><div class="notice">${t('El enlace oficial y la promoción se activarán en la versión definitiva. En este piloto no se comprueba la adhesión ni se entrega un regalo real.','The official link and promotion will be enabled in the final version. This pilot does not verify membership or grant a real gift.')}</div><button class="secondary" data-action="shop">${t('Ver tienda de muestra','View sample shop')}</button>`);return;}
 const e=EVENTS.find(e=>e.id===(node.id==='christmas-discount'?'christmas':'newyear'));openPanel(node.id,`<h2>${t('Una buena señal.','A good sign.')}</h2><p>${t('Has encontrado el descuento de muestra del 10% para','You found the sample 10% discount for')} ${lang==='es'?e.name:e.en}.</p>${couponHTML(e.code)}<button class="primary" data-event="${e.id}">${t('Ver el evento','View event')} ↗</button>${sampleNote()}`);
}
function couponHTML(code){return `<div class="coupon"><b>${code}</b><button data-copy="${code}">${t('Copiar','Copy')}</button></div>`;}
function rescue(){if(grant(p,'rescue',30)){save();toast(t('¡Rescate completado! +30 monedas','Rescue complete! +30 coins'));}visit(NODES.find(n=>n.id==='castaway'));}
function updateHUD(){const count=NODES.filter(n=>n.kind==='buoy'&&p.discovered.includes(n.id)).length;$('#buoy-count').textContent=`${count} / 6 BOIAS`;$('#coin-count').textContent=`${p.coins} ◇`;const target=waypoint||EVENTS.find(e=>!p.discovered.includes(e.id));$('#next-island').textContent=target?t(`Rumbo a ${target.name}`,`Course: ${target.en}`):t('Busca todas las sorpresas','Find every surprise');$('#passport-button').textContent=p.nickname||t('Mi pasaporte','My passport');}
function onFrame({dt,s,speed,drift}){if(speed>.2){p.activeSeconds+=dt;saveTimer+=dt;if(saveTimer>5){save();saveTimer=0;}for(const minutes of [5,20])if(p.activeSeconds>=minutes*60&&grant(p,'time-'+minutes,minutes===5?30:50)){toast(t(`Logro: ${minutes} minutos al timón`,`Achievement: ${minutes} minutes at the helm`));save();updateHUD();}}$('#speed-value').textContent=Math.round(speed*2);$('#drift-button').classList.toggle('active',drift);drawMap(s);}
function drawMap(s){const c=$('#minimap'),ctx=c.getContext('2d');ctx.clearRect(0,0,240,260);const px=x=>(x+65)/130*240,pz=z=>(z+101)/160*260;ctx.strokeStyle='#acdacf1b';ctx.lineWidth=1;for(let x=20;x<240;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,260);ctx.stroke();}for(let y=10;y<260;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(240,y);ctx.stroke();}ctx.setLineDash([4,5]);ctx.beginPath();ctx.moveTo(px(0),pz(41));EVENTS.forEach(e=>ctx.lineTo(px(e.dock.x),pz(e.dock.z)));ctx.strokeStyle='#b9dcd366';ctx.stroke();ctx.setLineDash([]);EVENTS.forEach((e,i)=>{ctx.fillStyle=p.discovered.includes(e.id)?'#e9e4c3':e.color;ctx.beginPath();ctx.ellipse(px(e.x),pz(e.z),e.r*1.6,e.r*1.4,.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#173f4e';ctx.font='bold 14px Arial';ctx.textAlign='center';ctx.fillText(`${i+1}`,px(e.x),pz(e.z)+5);});for(const n of NODES){ctx.fillStyle=p.discovered.includes(n.id)?'#ffffff88':n.color;ctx.beginPath();ctx.arc(px(n.x),pz(n.z),n.kind==='buoy'?3.5:2.4,0,Math.PI*2);ctx.fill();}ctx.save();ctx.translate(px(s.x),pz(s.z));ctx.rotate(-s.heading);ctx.fillStyle='#ff7042';ctx.beginPath();ctx.moveTo(0,9);ctx.lineTo(-5,-5);ctx.lineTo(0,-2);ctx.lineTo(5,-5);ctx.closePath();ctx.fill();ctx.restore();const target=waypoint||EVENTS.find(e=>!p.discovered.includes(e.id));if(target){const angle=Math.atan2(target.dock.x-s.x,-(target.dock.z-s.z))*180/Math.PI;$('#compass').style.transform=`rotate(${angle}deg)`;$('#compass').textContent='↑';}else{$('#compass').style.transform='';$('#compass').textContent='N';}}
function onNearby(n){nearby=n;$('#interact').hidden=!n;$('#interact').textContent=n?`${p.discovered.includes(n.id)?'✓ ':''}${lang==='es'?n.es:n.en} ↗`:'';}
function clearControls(){primaryPointer=null;secondPointer=null;origin=null;$('#joystick').hidden=true;if(world){world.input={x:0,y:0,active:false,drift:false};world.keys.clear();}}
const actions={enter:()=>{closePanel();transition('home');},home:()=>{closePanel();transition('home');},explore:()=>explore(),tickets,artists,gallery:()=>gallery(),shop,philosophy,passport:()=>passport(),editPassport:()=>passport(true),boat:boatPanel,achievements,bottle,rescue,mute:()=>{stopRadio();soundPanel();},resume:closePanel,dismissTutorial:()=>$('#tutorial').hidden=true,checkout:el=>checkout(el.dataset.id)};
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-action]');if(!el)return;
 if(el.dataset.action){actions[el.dataset.action]?.(el);return;}if(el.dataset.event){eventPanel(el.dataset.event);return;}if(el.dataset.sail){explore(el.dataset.sail);return;}if(el.dataset.gallery){gallery(el.dataset.gallery);return;}if(el.dataset.artist!==undefined){artistPanel(Number(el.dataset.artist));return;}if(el.dataset.product!==undefined){product(Number(el.dataset.product));return;}if(el.dataset.track!==undefined){playTrack(Number(el.dataset.track));return;}if(el.dataset.color){p.color=el.dataset.color;save();world?.setBoat(p.color,p.flag,p.trail);boatPanel();return;}if(el.dataset.buy){const id=el.dataset.buy,cost=id==='flag'?40:60;if(!buy(p,id,cost)){toast(t('Explora un poco más para conseguir monedas.','Explore a little more to earn coins.'));return;}p[id]=!p[id];save();world?.setBoat(p.color,p.flag,p.trail);updateHUD();boatPanel();return;}
 if(el.dataset.copy){try{await navigator.clipboard.writeText(el.dataset.copy);toast(t('Código de muestra copiado','Sample code copied'));}catch{toast(t('Puedes seleccionar y copiar el código que aparece en pantalla.','Select and copy the code shown on screen.'));}}
});
document.addEventListener('submit',e=>{if(e.target.id==='passport-form'){e.preventDefault();const d=new FormData(e.target),nickname=String(d.get('nickname')||'').trim();if(!nickname){toast(t('Escribe un apodo para tu pasaporte.','Enter a nickname for your passport.'));return;}for(const key of ['nickname','genres','artist','memory','message'])p[key]=String(d.get(key)||'').trim();save();updateHUD();passport();toast(t('Pasaporte guardado en este navegador','Passport saved in this browser'));}else if(e.target.id==='survey-form'){e.preventDefault();const d=new FormData(e.target);if(!String(d.get('next')||'').trim())return;p.survey=Object.fromEntries(d);const reward=grant(p,'survey',20);save();updateHUD();closePanel();toast(reward?t('Respuesta guardada. +20 monedas','Response saved. +20 coins'):t('Respuesta actualizada','Response updated'));}});
$('#close-panel').addEventListener('click',closePanel);$('#panel').addEventListener('close',()=>{if(world)world.paused=false;modalId='';});$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){const r=$('#panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});
$('#lang').addEventListener('click',()=>{lang=lang==='es'?'en':'es';save();translate();window.dispatchEvent(new Event('boia-language'));});
$('#interact').addEventListener('click',()=>visit(nearby));
$('#minimap').addEventListener('click',()=>window.dispatchEvent(new Event('boia-map')));
const canvas=$('#world');canvas.addEventListener('pointerdown',e=>{if(screen!=='game'||!world||world.paused||e.button!==0)return;if(primaryPointer!==null&&e.pointerId!==primaryPointer){secondPointer=e.pointerId;world.input.drift=true;canvas.setPointerCapture(e.pointerId);return;}if(!world.hitBoat(e)){toast(t('Toca el barco para empezar a moverlo.','Touch the boat to start moving.'));return;}e.preventDefault();primaryPointer=e.pointerId;origin={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);world.input={x:0,y:0,active:true,drift:false};$('#joystick').style.left=e.clientX+'px';$('#joystick').style.top=e.clientY+'px';$('#joystick div').style.transform='';$('#joystick').hidden=false;$('#map-wrap').hidden=false;$('#tutorial').hidden=true;});
canvas.addEventListener('pointermove',e=>{if(e.pointerId!==primaryPointer||!origin||!world)return;e.preventDefault();const dx=e.clientX-origin.x,dy=e.clientY-origin.y,r=Math.max(46,Math.hypot(dx,dy));world.input.x=dx/r;world.input.y=dy/r;$('#joystick div').style.transform=`translate(${dx/r*40}px,${dy/r*40}px)`;});
function pointerEnd(e){if(e.pointerId===secondPointer){secondPointer=null;if(world)world.input.drift=false;}if(e.pointerId===primaryPointer){clearControls();}if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);}
for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,pointerEnd);
$('#drift-button').addEventListener('pointerdown',e=>{if(!world)return;e.preventDefault();world.input.drift=true;e.currentTarget.setPointerCapture(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('#drift-button').addEventListener(ev,()=>{if(world)world.input.drift=false;});
document.addEventListener('keydown',e=>{if(screen!=='game'||!world||world.paused)return;const key=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','shift'].includes(key)){e.preventDefault();world.keys.add(key);$('#map-wrap').hidden=false;$('#tutorial').hidden=true;}if(key==='e'&&nearby)visit(nearby);});document.addEventListener('keyup',e=>world?.keys.delete(e.key.toLowerCase()));window.addEventListener('blur',clearControls);document.addEventListener('visibilitychange',()=>{if(document.hidden){clearControls();save();stopRadio();}});window.addEventListener('pagehide',save);
translate();setScreen('welcome');
function failed3D(){document.body.classList.add('no-webgl');world=null;if(screen==='game'){$('#fallback').hidden=false;}else toast(t('Puedes visitar el festival. El 3D no está disponible en este navegador.','You can visit the festival. 3D is unavailable in this browser.'));}
try{world=new SeaWorld(canvas,{onFrame,onFirstMove:()=>{$('#map-wrap').hidden=false;},onNearby,onError:failed3D});world.setBoat(p.color,p.flag,p.trail);}catch(err){console.warn('BOIA 3D unavailable',err.message);failed3D();}
const {installUpgrade}=await import('./upgrade.mjs');
installUpgrade({get p(){return p},set p(v){p=v},get lang(){return lang},setLang(v){lang=v;translate();save();window.dispatchEvent(new Event('boia-language'));},get screen(){return screen},get world(){return world},get waypoint(){return waypoint},set waypoint(v){waypoint=v;updateHUD();},actions,setTravelHandler(fn){travelHandler=fn;},t,esc,toast,save,translate,setScreen,transition,explore,openPanel,closePanel,poster,eventPanel,artists,artistPanel,gallery,shop,product,philosophy,soundPanel,stopRadio,grant,discover,rank,clearControls,visit,get nearby(){return nearby},replaceVisit(fn){visit=fn},replaceDrawMap(fn){drawMap=fn},replaceUpdateHUD(fn){updateHUD=fn},updateHUD});

window.addEventListener('boia-volume',ev=>{if(radio)radio.master.gain.setTargetAtTime(Math.max(0,Math.min(1,ev.detail)),radio.ctx.currentTime,.06);});
